steps.command:
cd /app/logs; total=0; bad=0; mismatch=0;
for f in *.log; do fd=${f%%_*};
  while IFS= read -r line; do
    total=$((total+1));
    case "$line" in
      [0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]\ [0-9][0-9]:[0-9][0-9]:[0-9][0-9]\ \[*) ;;
      *) bad=$((bad+1)); if [ $bad -le 10 ]; then echo "BAD: $f: $line"; fi;;
    esac
    ld=${line%% *};
    if [ "$ld" != "$fd" ]; then mismatch=$((mismatch+1)); if [ $mismatch -le 5 ]; then echo "MISMATCH $f vs $ld"; fi; fi
  done < "$f";
done; echo "total=$total bad=$bad mismatch=$mismatch"

awk '
BEGIN{ split("2025-08-12 2025-08-06 2025-07-14 2025-08-01 0000-00-00", s, " ") }
{
  d=$1; sev=$3; gsub(/[\[\]]/,"",sev)
  if (sev!="ERROR" && sev!="WARNING" && sev!="INFO") next
  if (d==s[1]) {t[sev]++; }
  if (d>=s[2] && d<=s[1]) {w[sev]++}
  if (d>=s[3] && d<=s[1]) {m[sev]++}
  if (d>=s[4] && d<=s[1]) {mt[sev]++}
  a[sev]++
}
END{
  split("ERROR WARNING INFO", o, " ")
  print "period,severity,count"
  for(i=1;i<=3;i++) print "today," o[i] "," t[o[i]]+0
  for(i=1;i<=3;i++) print "last_7_days," o[i] "," w[o[i]]+0
  for(i=1;i<=3;i++) print "last_30_days," o[i] "," m[o[i]]+0
  for(i=1;i<=3;i++) print "month_to_date," o[i] "," mt[o[i]]+0
  for(i=1;i<=3;i++) print "total," o[i] "," a[o[i]]+0
}' *.log > /app/summary.csv; cat /app/summary.csv
